import{_ as e,r as s,o,c,e as a,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"|resize - October CMS - 3.x","titleTemplate":false,"description":"Twig-фильтр","frontmatter":{"subtitle":"Twig-фильтр"},"headers":[{"level":2,"title":"Пользовательские имена файлов","slug":"пользовательские-имена-фаилов","link":"#пользовательские-имена-фаилов","children":[]},{"level":2,"title":"Пользовательские имена папок","slug":"пользовательские-имена-папок","link":"#пользовательские-имена-папок","children":[]},{"level":2,"title":"Доступные источники","slug":"доступные-источники","link":"#доступные-источники","children":[]},{"level":2,"title":"PHP-интерфейс","slug":"php-интерфеис","link":"#php-интерфеис","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/markup/filter/resize.md","filePath":"3.x/ru/markup/filter/resize.md"}'),i={name:"3.x/ru/markup/filter/resize.md"};function r(k,n,g,d,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"|resize",-1)),a(p),n[1]||(n[1]=u(`<p>Фильтр <code>|resize</code> пытается изменить размер предоставленного источника изображения, используя заданную конфигурацию изменения размера, и выводит URL к изменённому изображению.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>image.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">100</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>Фильтр принимает три аргумента: <code>|resize(width, height, options)</code>.</p><p>Если фильтр может изменить размер предоставленного изображения, возвращается URL к ресайзеру изображений (например: <code>/resize/filename.png</code>). При последующих запросах возвращается прямой URL к изменённому изображению. Если фильтр не может обработать предоставленное изображение, он возвращает оригинальный URL без изменений.</p><p>Следующий пример изменит размер медиа-изображения banner.jpg до соотношения 1920 x 1080.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media<span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">1920</span><span class="token punctuation">,</span> <span class="token number">1080</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Вы также можете передать третий аргумент с опциями. В этом примере изображение будет обрезано.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> mode<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>crop<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Подробнее о доступных параметрах <code>options</code> см. в <a href="./../../extend/services/resizer.html">статье о ресайзере изображений</a>.</p><h2 id="пользовательские-имена-фаилов"><a href="#пользовательские-имена-фаилов" class="header-anchor">#</a> Пользовательские имена файлов</h2><p>По умолчанию ресайзер присваивает случайное имя файла изменённым изображениям. Вы можете использовать оригинальное имя файла, передав <code>true</code> в опцию <code>filename</code> ресайзера.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> filename<span class="token punctuation">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Опция <code>filename</code> также поддерживает пользовательское имя файла в виде строки. Имя файла не должно содержать расширение, так как используется оригинальное.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Вы можете изменить расширение с помощью опции <code>extension</code>. Этот процесс попытается конвертировать один тип файла в другой, например, JPG в PNG.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span>
    extension<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>png<span class="token punctuation">&#39;</span></span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><h2 id="пользовательские-имена-папок"><a href="#пользовательские-имена-папок" class="header-anchor">#</a> Пользовательские имена папок</h2><p>При использовании пользовательских имён файлов имя файла всё ещё будет содержать хэш в конце для обеспечения уникальности в директории ресурсов ресайзера. В большинстве случаев этого достаточно для удовлетворения базовых требований SEO. Например, файл будет выглядеть в системе следующим образом.</p><ul><li><code>.../800_600_0_0_auto/my-seo-friendly-name_001a14981ffe90700046616c5f415467.png</code></li></ul><p>Можно указать <code>group</code> в качестве имени папки — это поместит изображение в выделенную группу ресурсов.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>banner.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
    filename<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>my-seo-friendly-name<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span>
    group<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>2024-banners<span class="token punctuation">&#39;</span></span>
<span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><p>Например, приведённый выше код поместит файл в следующую директорию:</p><ul><li><code>.../800_600_0_0_auto/2024-banners/my-seo-friendly-name.png</code></li></ul><p>Однако имейте в виду, что этот подход подвержен конфликтам имён. Если другой файл будет изменён с тем же именем и параметрами, он выведет оригинальный файл, так как к пути не добавляется уникальный хэш.</p><h2 id="доступные-источники"><a href="#доступные-источники" class="header-anchor">#</a> Доступные источники</h2><p>Вы можете ссылаться на изображения из нескольких источников, включая следующие пути:</p><ul><li><code>/app</code></li><li><code>/plugins</code></li><li><code>/themes</code></li><li><code>/modules</code></li><li><code>/storage/app/uploads</code></li><li><code>/storage/app/media</code></li></ul><p>Например:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>/plugins/acme/blog/assets/images/someimage.png<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>resize<span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h2 id="php-интерфеис"><a href="#php-интерфеис" class="header-anchor">#</a> PHP-интерфейс</h2><p>Вы можете изменять размер изображений в PHP с помощью класса <code>System\\Classes\\ResizeImages</code> и метода <code>resize</code>. Возвращаемое значение — URL к изменённому изображению.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/asset.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Метод принимает ширину (второй аргумент), высоту (третий аргумент) и <a href="./../../extend/services/resizer.html">опции ресайзера</a> (четвёртый аргумент).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">ResizeImages</span><span class="token operator">::</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/asset.jpg&#39;</span><span class="token punctuation">,</span> <span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../extend/services/resizer.html">Сервис ресайзера</a></li></ul></div>`,36))])}const w=e(i,[["render",r]]);export{f as __pageData,w as default};
